<?php
// Customer shopping cart.

    $items = query('SELECT b.*, SUM(k.qty) AS qty FROM keranjang k JOIN tb_barang b ON b.id_barang=k.id_barang WHERE k.id_user=? GROUP BY b.id_barang', [$userId]);
    page_title('YOUR SHOPPING BAG', 'Keranjang Anda.', 'Periksa pilihan Anda sebelum melanjutkan ke pembayaran.');
    if (!$items) empty_state('Keranjang masih kosong', 'Temukan perangkat favorit Anda dan tambahkan ke sini.');
    else { ?>
    <form method="post" id="checkout-selection"><?= csrf() ?><input type="hidden" name="action" value="checkout"></form><div class="checkout-layout"><section class="panel cart-items"><?php foreach ($items as $item): ?><article class="cart-row"><input aria-label="Pilih <?= e($item['nama_barang']) ?>" type="checkbox" name="selected[]" value="<?= (int)$item['id_barang'] ?>" form="checkout-selection" data-cart-price="<?= (int)$item['harga']*(int)$item['qty'] ?>" checked><a href="<?= e(url('pages/deskripsi.php?id=' . $item['id_barang'])) ?>"><img src="<?= e(url($item['img'])) ?>" alt="<?= e($item['nama_barang']) ?>"></a><div class="cart-product"><small class="eyebrow"><?= e($item['merk']) ?></small><a href="<?= e(url('pages/deskripsi.php?id=' . $item['id_barang'])) ?>"><strong><?= e($item['nama_barang']) ?></strong></a><p><?= rupiah($item['harga']) ?></p><small class="muted">Stok: <?= (int)$item['stok'] ?></small><form method="post" class="quantity-form"><?= csrf() ?><input type="hidden" name="id" value="<?= (int)$item['id_barang'] ?>"><input aria-label="Jumlah produk" type="number" min="1" max="<?= max(1,(int)$item['stok']) ?>" name="qty" value="<?= (int)$item['qty'] ?>" required><button class="button small secondary" name="action" value="update">Perbarui</button><button class="text-button danger-text" name="action" value="remove" formnovalidate>Hapus</button></form></div><strong><?= rupiah($item['harga']*$item['qty']) ?></strong></article><?php endforeach; ?></section><aside class="panel summary"><span class="eyebrow">SELANGKAH LEBIH DEKAT</span><h2>Ringkasan belanja</h2><div class="summary-line"><span>Subtotal pilihan</span><strong data-cart-total><?= rupiah(array_sum(array_map(function($i){return $i['harga']*$i['qty'];},$items))) ?></strong></div><p class="muted small-text">Biaya pengiriman dan pembayaran dihitung saat checkout.</p><button form="checkout-selection" class="button wide">Lanjut checkout <?= icon('arrow') ?></button><a class="filter-reset" href="<?= e(url('pages/product.php')) ?>">Lanjutkan belanja</a></aside></div>
    <?php }
